import {openStudioDb,transact,requestResult} from '../../src/infrastructure/storage/database';
import {f} from '../helpers/fixtures';
export async function seedPromptLibrary(){const db=await openStudioDb();try{await transact(db,db.tables.slice(),'readwrite',tx=>{for(const table of db.tables)tx.objectStore(table).clear();tx.objectStore('projects').put(f.project({title:'提示词项目'}));tx.objectStore('graphs').put(f.graph({nodes:[{id:'text-1',type:'text',title:'旧文字',x:40,y:40,locked:false,data:{kind:'text',text:'原稿未改',referenceTokens:[]}}]}));tx.objectStore('prompts').put({id:'template',title:'品牌模板',body:'{{人物}}展示康济健葆，保持不切镜。',tags:['广告'],variables:['人物'],source:'用户提供的测试来源',license:'测试授权说明',revision:1,starred:false,trashed:false});tx.objectStore('prompts').put({id:'plain',title:'本地示例',body:'雨后的街道。',tags:['场景'],variables:[],source:'本地原创测试夹具',license:'测试夹具许可',revision:1,starred:false,trashed:false});});}finally{db.close();}}
export async function promptState(){const db=await openStudioDb();try{return await transact(db,['prompts','graphs','runs','receipts'],'readonly',async tx=>({prompts:await requestResult(tx.objectStore('prompts').getAll()),graph:await requestResult(tx.objectStore('graphs').get('p1')),runs:await requestResult(tx.objectStore('runs').getAll()),receipts:await requestResult(tx.objectStore('receipts').getAll())}));}finally{db.close();}}
